#include <bits/stdc++.h>
using namespace std;using I=long long;using G=vector<int>;using P=array<I,7>;
void need(bool q,string s){if(!q)throw runtime_error(s);}
void valid(G a){int n=a.size();for(int i=0;i<n;i++){need(a[i]>=0&&a[i]<(1<<n)&&!(a[i]>>i&1),"row");for(int j=0;j<i;j++)need(((a[i]>>j&1)+(a[j]>>i&1))==1,"pair");}}
P count(G a,int root=0){valid(a);int n=a.size(),N=1<<n,F=N-1;vector<I>en(N*n),st(N*n),H(N);H[0]=1;for(int i=0;i<n;i++)en[(1<<i)*n+i]=st[(1<<i)*n+i]=1;for(int S=1;S<N;S++)for(int v=0;v<n;v++)if(S>>v&1){int A=S^(1<<v);for(int w=0;w<n;w++)if(A>>w&1){if(a[w]>>v&1)en[S*n+v]+=en[A*n+w];else st[S*n+v]+=st[A*n+w];}H[S]+=en[S*n+v];}I L=0,R=0,b=0;for(int S=0;S<N;S++){L+=en[S*n+root]*H[F^S];R+=st[S*n+root]*H[F^S];}int D=F^(1<<root),A=D;while(true){b+=H[A]*H[D^A];if(!A)break;A=(A-1)&D;}return {H[F],st[F*n+root],en[F*n+root],L,R,H[D],b};}
G relabel(G a,int root){vector<int>ord{root};for(int i=0;i<(int)a.size();i++)if(i!=root)ord.push_back(i);G b(a.size());for(int i=0;i<(int)a.size();i++)for(int j=0;j<(int)a.size();j++)if(a[ord[i]]>>ord[j]&1)b[i]|=1<<j;return b;}
G move(G a,char op){int n=a.size();for(auto&x:a)x|=1<<n;a.push_back(0);if(op!='O'){a[0]^=1<<n;a[n]=1;}if(op=='J')a=relabel(a,n);return a;}
P trans(P p,char op){auto[h,s,e,L,R,d,b]=p;if(op=='O')return {h,s,0,L,2*R,d,2*b};need(op=='Z',"unsupported transfer");return{h+R-e,s,d,L+b,2*R-d,d,2*b};}
I X(P p,int j){return p[0]+p[3]-p[1]+2*j;}
array<I,4> row(P p,int j){return {X(p,j),p[2],p[4]+p[6],p[5]};}
bool strong(G a){int n=a.size(),F=(1<<n)-1;for(int v=0;v<n;v++)a[v]|=1<<v;for(int k=0;k<n;k++)for(int v=0;v<n;v++)if(a[v]>>k&1)a[v]|=a[k];return all_of(a.begin(),a.end(),[&](int x){return x==F;});}
int main(){array<array<G,2>,4> seeds={{{G{2,12,17,101,75,23,167,63},G{2,12,17,165,43,71,31,119}},{G{2,44,49,133,11,89,31,119},G{2,52,25,35,105,197,15,95}},{G{2,148,97,7,45,75,27,125},G{2,148,41,67,45,75,23,125}},{G{4,9,50,85,163,75,151,47},G{4,9,50,85,99,139,167,31}}}};int roots[]={2,1,0,2};int js[4][2]={{3,3},{4,3},{4,3},{5,5}};array<array<P,2>,4> expected={{{P{165,10,27,516,237,49,824},P{175,11,27,507,249,49,812}},{P{253,13,29,511,287,29,640},P{253,11,29,511,287,29,640}},{P{259,13,101,1293,267,109,1424},P{259,11,101,1293,267,109,1424}},{P{295,16,33,532,359,33,720},P{293,17,33,535,359,33,720}}}};I bases[]={677,759,1547,821},coef[]={1012,898,1582,1046},constant[]={-313,-139,-27,-225};int checked=0;
 for(int i=0;i<4;i++){for(int r=0;r<2;r++){seeds[i][r]=relabel(seeds[i][r],roots[i]);need(count(seeds[i][r])==expected[i][r],"base profile");need(expected[i][r][1]==r+1+3*js[i][r],"stagger starts");need(X(expected[i][r],js[i][r])==bases[i],"base");}need(row(expected[i][0],js[i][0])==row(expected[i][1],js[i][1]),"initial pair");
 function<void(array<G,2>,array<P,2>,string)>walk=[&](array<G,2> a,array<P,2> ps,string word){for(int r=0;r<2;r++){P actual=count(a[r]);checked++;need(actual==ps[r],"literal transfer "+word);need(ps[r][1]==r+1+3*js[i][r],"starts preserved");}need(row(ps[0],js[i][0])==row(ps[1],js[i][1]),"paired row "+word);need(X(ps[0],js[i][0])>=137,"base floor");if(word.size()==5)return;for(char op:string("OZ")){array<G,2>aa;array<P,2>pp;for(int r=0;r<2;r++){aa[r]=move(a[r],op);pp[r]=trans(ps[r],op);}walk(aa,pp,word+op);}};walk(seeds[i],expected[i],"");
 for(int r=0;r<2;r++){P p=expected[i][r];for(int k=1;k<=20;k++){p=trans(p,'Z');need(X(p,js[i][r])==coef[i]*(1LL<<k)+constant[i],"Z formula");}}
 }
 // The paired row fails after J, so J is deliberately outside Theorem1.
 need(X(count(move(seeds[1][0],'J')),js[1][0])==4379,"J hostile1");need(X(count(move(seeds[1][1],'J')),js[1][1])==4547,"J hostile2");
 G u{2,0};int families=0;vector<array<I,6>> receipts;
 for(int n=3;n<=14;n++){u=move(u,'J');need((int)u.size()==n&&strong(u),"U strong");need(count(u,0)[1]==1&&count(u,1)[1]==1,"two unit roots");if(n<4)continue;G w=u;for(int k=2;k<n;k++)w[k]|=1<<n;w.push_back(3);need(strong(w),"W strong");P p=count(w,n);need(p[1]==2,"W start2");I e=p[2],gap=p[5]-e,extra=p[4]-p[0]+e-p[5];need(e>0&&gap>0&&extra>0,"strict interior");need(p[5]>=n,"unbounded deletion count");receipts.push_back({n+1,p[0],p[1],e,gap,extra});families++;}
 cout<<"{\n  \"status\": \"PASS\",\n  \"paired_literal_graphs\": "<<checked<<",\n  \"common_word_max_length\": 5,\n  \"pure_Z_formula_max_k\": 20,\n  \"irreducible_family_graphs\": "<<families<<",\n  \"irreducible_rows_order_h_s_e_d_minus_e_f\": [\n";for(int i=0;i<(int)receipts.size();i++){cout<<"    [";for(int j=0;j<6;j++){if(j)cout<<", ";cout<<receipts[i][j];}cout<<"]"<<(i+1==(int)receipts.size()?"\n":",\n");}cout<<"  ],\n  \"F_8_137\": \"OPEN\"\n}\n";
}
